571		}
572		if !vok {
573			fail(fmt.Errorf("%w: %s", govflow.ErrProposalNotFound, *id))
574		}
575		if cf.asJSON {
576			emitJSON(voteView)
577			return
578		}
579		printVoteProposalText(voteView)
