3	import (
4		"errors"
5		"reflect"
6		"strings"
7		"testing"
8	)
9	
10	// TestExecutedProposalVoteRetryReturnsFirstBallot：已执行投票提案的投票重试
11	// 回归保障。重点保留一种真实情况：
12	//
13	//	frank→erin→dave 多跳委托，最终代表 dave 归集沿途成员权重投反对票；
14	//	alice 归集 bob、carol 的委托权重投赞成，赞成权重仍达到法定人数并形成
15	//	严格多数，提案经成员投票、截止计票、时间锁到期执行后变为 executed。
16	//
17	// 执行之后：
18	//   - 投过票的最终代表（赞成者与反对者）再次提交同一选择，无论传入时间早于
19	//     开始还是晚于截止，都必须取回首次票据：原代表编号、完整归集权重（含
20	//     沿途委托成员，不退回本人权重）、原选择、首次投票时间；票据与提案查询
21	//     中的原记录逐字一致，重试不落盘任何变化。
22	//   - 反对代表改为赞成必须明确报改投冲突（ErrProposalConflict），不能把
23	//     反对票覆盖成赞成，也不能仅因提案已执行就改报普通的投票关闭错误。
24	//   - 始终没有投票的最终代表此时提交首次选择，即使传入原投票窗口内的时间，
25	//     也必须因已经计票被拒绝（ErrVoteRejected），不能借旧时间追加票据。
26	//   - 两种失败都不得返回看似成功的新票。
27	//
28	// 全部重试与失败之后：提案仍为 executed；票据数量、顺序、选择、权重与首次
29	// 时间保持原样；首次计票的赞成、反对、参与权重与计票时间保持原样；资金库
30	// 与收款账户余额停留在首次执行后的数值；成功执行凭据仍是原来的一份，
31	// order/执行时间/动作留痕不变。重开状态文件后结论一致。
32	//
33	// 直接 register 登记并执行的 passed 提案没有投票留痕：投票入口在该编号上
34	// 只能得到“提案不存在”，不能代替本用例要求的投票→计票→执行使用条件。
35	func TestExecutedProposalVoteRetryReturnsFirstBallot(t *testing.T) {
36		store, path := openTempStore(t, 1000)
37		defer store.Close()
38	
39		const id = "gip-exec-retry"
40		in := &CreateVoteInput{
41			ID: id,
42			Members: []VoteMember{
43				{ID: "alice", Weight: 300},
44				{ID: "bob", Weight: 200},
45				{ID: "carol", Weight: 100},
46				// 多跳链 frank→erin→dave：dave 是最终代表，归集 50+50+50=150。
47				{ID: "dave", Weight: 50},
48				{ID: "erin", Weight: 50},
49				{ID: "frank", Weight: 50},
50				// 始终没有投票的最终代表，执行之后再尝试投首次票。
51				{ID: "gina", Weight: 100},
52			},
53			Delegations: []Delegation{
54				{From: "bob", To: "alice"},
55				{From: "carol", To: "alice"},
56				{From: "erin", To: "dave"},
57				{From: "frank", To: "erin"},
58			},
59			// 总权重 850；参与只有 alice(600)+dave(150)=750，达到法定人数 600，
60			// 且赞成 600 严格多于反对 150。
61			Quorum:      600,
62			StartAt:     100,
63			Deadline:    200,
64			TimelockEnd: 300,
65			Actions:     []string{"transfer:audits:100"},
66		}
67		view := mustCreateVote(t, store, in)
68		if view.State != "voting" {
69			t.Fatalf("new proposal state=%s, want voting", view.State)
70		}
71	
72		// 委托路径、最终代表与归集权重：frank 的两跳链必须完整保留到 dave。
73		wantPath := map[string][]string{
74			"alice": {"alice"},
75			"bob":   {"bob", "alice"},
76			"carol": {"carol", "alice"},
77			"dave":  {"dave"},
78			"erin":  {"erin", "dave"},
79			"frank": {"frank", "erin", "dave"},
80			"gina":  {"gina"},
81		}
82		wantHead := map[string]string{
83			"alice": "alice", "bob": "alice", "carol": "alice",
84			"dave": "dave", "erin": "dave", "frank": "dave", "gina": "gina",
85		}
86		for _, m := range view.Members {
87			if !equalStrings(m.Path, wantPath[m.ID]) {
88				t.Fatalf("member %s path=%v, want %v", m.ID, m.Path, wantPath[m.ID])
89			}
90			if m.Delegate != wantHead[m.ID] {
91				t.Fatalf("member %s final representative=%s, want %s", m.ID, m.Delegate, wantHead[m.ID])
92			}
93		}
94	
95		// 只有最终代表能投票：委托链上的 erin、frank 不能代替 dave 投票。
96		if _, err := store.CastVote(id, "erin", false, 150); !errors.Is(err, ErrVoteRejected) {
97			t.Fatalf("delegated erin voted directly: %v", err)
98		}
99		if _, err := store.CastVote(id, "frank", false, 150); !errors.Is(err, ErrVoteRejected) {
100			t.Fatalf("delegated frank voted directly: %v", err)
101		}
102	
103		// 反对票先投（150），赞成票后投（160）：固定票据顺序为 dave、alice。
104		againstFirst, err := store.CastVote(id, "dave", false, 150)
105		if err != nil {
106			t.Fatalf("dave against vote: %v", err)
107		}
108		// 归集权重必须包含沿途委托成员 erin、frank：150，而不是 dave 本人的 50。
109		if againstFirst.Representative != "dave" || againstFirst.Weight != 150 ||
110			againstFirst.Support || againstFirst.VotedAt != 150 {
111			t.Fatalf("dave first ballot=%+v, want dave/150/against/150", againstFirst)
112		}
113		forFirst, err := store.CastVote(id, "alice", true, 160)
114		if err != nil {
115			t.Fatalf("alice for vote: %v", err)
116		}
117		if forFirst.Representative != "alice" || forFirst.Weight != 600 ||
118			!forFirst.Support || forFirst.VotedAt != 160 {
119			t.Fatalf("alice first ballot=%+v, want alice/600/for/160", forFirst)
120		}
121	
122		// 截止计票：赞成 600、反对 150、参与 750，达到法定人数且严格多数 => 通过。
123		tally, err := store.TallyVote(id, 200)
124		if err != nil {
125			t.Fatalf("tally: %v", err)
126		}
127		if !tally.Passed || tally.ForWeight != 600 || tally.AgainstWeight != 150 ||
128			tally.Turnout != 750 || tally.Quorum != 600 || tally.TalliedAt != 200 {
129			t.Fatalf("tally=%+v, want passed for=600 against=150 turnout=750 quorum=600 at=200", tally)
130		}
131		passed, ok, err := store.VoteProposal(id)
132		if err != nil || !ok || passed.State != "passed" {
133			t.Fatalf("state after tally state=%s ok=%v err=%v, want passed", passed.State, ok, err)
134		}
135	
136		// 时间锁到期执行：真实转账一次，状态转为 executed。
137		receipt, err := store.Execute(id, 300)
138		if err != nil {
139			t.Fatalf("execute: %v", err)
140		}
141		if receipt.Order != 0 || receipt.ExecutedAt != 300 || receipt.ProposalID != id ||
142			len(receipt.Actions) != 1 || receipt.Actions[0].Index != 0 ||
143			receipt.Actions[0].Action != "transfer:audits:100" {
144			t.Fatalf("first receipt=%+v, want order=0 executed_at=300 one action index=0", receipt)
145		}
146		if bal, _ := store.TreasuryBalance(); bal != 900 {
147			t.Fatalf("treasury after execute=%d, want 900", bal)
148		}
149		if bal, _ := store.Balance("audits"); bal != 100 {
150			t.Fatalf("audits balance=%d, want 100", bal)
151		}
152		execView, _, err := store.VoteProposal(id)
153		if err != nil || execView.State != "executed" || !execView.Tally.Passed {
154			t.Fatalf("state after execute state=%s tally=%+v err=%v, want executed/passed",
155				execView.State, execView.Tally, err)
156		}
157	
158		// ---- 执行之后：原代表同选择重试始终取回首次票据 ----
159	
160		// 反对代表：传入早于开始时刻的时间，不能替换原票时间，也不能再套
161		// 首次投票的时间窗口把它判成窗口外失败。
162		againEarly, err := store.CastVote(id, "dave", false, 50)
163		if err != nil {
164			t.Fatalf("dave identical retry before start: %v", err)
165		}
166		if !reflect.DeepEqual(againEarly, againstFirst) {
167			t.Fatalf("dave retry(50)=%+v, want first ballot %+v", againEarly, againstFirst)
168		}
169		// 反对代表：传入晚于截止（也晚于执行）的时间，结果完全相同。
170		againLate, err := store.CastVote(id, "dave", false, 9999)
171		if err != nil {
172			t.Fatalf("dave identical retry after deadline: %v", err)
173		}
174		if !reflect.DeepEqual(againLate, againstFirst) {
175			t.Fatalf("dave retry(9999)=%+v, want first ballot %+v", againLate, againstFirst)
176		}
177		// 赞成代表同样能从原投票入口取回自己的记录（早于开始的时间）。
178		againFor, err := store.CastVote(id, "alice", true, 99)
179		if err != nil {
180			t.Fatalf("alice identical retry before start: %v", err)
181		}
182		if !reflect.DeepEqual(againFor, forFirst) {
183			t.Fatalf("alice retry(99)=%+v, want first ballot %+v", againFor, forFirst)
184		}
185	
186		// 重试取回的票据必须与提案查询中的原记录逐字一致（代表、归集权重、
187		// 选择、首次时间），而不是新构造的票。
188		queried, _, err := store.VoteProposal(id)
189		if err != nil {
190			t.Fatal(err)
191		}
192		if len(queried.Ballots) != 2 {
193			t.Fatalf("ballot count after retries=%d, want 2", len(queried.Ballots))
194		}
195		if !reflect.DeepEqual(queried.Ballots[0], *againLate) {
196			t.Fatalf("retried dave ballot=%+v differs from query record=%+v",
197				againLate, queried.Ballots[0])
198		}
199		if !reflect.DeepEqual(queried.Ballots[1], *againFor) {
200			t.Fatalf("retried alice ballot=%+v differs from query record=%+v",
201				againFor, queried.Ballots[1])
202		}
203	
204		// ---- 执行之后：改投必须明确报改投冲突 ----
205	
206		// 反对代表改为赞成：ErrProposalConflict，错误必须说明“已投过反对、
207		// 不允许改投”；不能仅因已执行就退化成普通的投票关闭错误，
208		// 也不能把反对票覆盖成赞成。
209		change, err := store.CastVote(id, "dave", true, 150)
210		if !errors.Is(err, ErrProposalConflict) {
211			t.Fatalf("change vote err=%v, want ErrProposalConflict", err)
212		}
213		if change != nil {
214			t.Fatalf("change vote returned a success-looking ballot: %+v", change)
215		}
216		if msg := err.Error(); !containsAll(msg, "already voted against", "changing the vote is not allowed") {
217			t.Fatalf("change-vote error %q must report the vote-change conflict, not a plain closed error", msg)
218		}
219		if errors.Is(err, ErrVoteRejected) {
220			t.Fatalf("change vote must stay ErrProposalConflict, got vote-rejected: %v", err)
221		}
222		// 即便传入晚于执行的时间，分类仍是改投冲突。
223		if _, err := store.CastVote(id, "dave", true, 9999); !errors.Is(err, ErrProposalConflict) {
224			t.Fatalf("change vote after execution err=%v, want ErrProposalConflict", err)
225		}
226		// 赞成代表反向改投同样是冲突。
227		if _, err := store.CastVote(id, "alice", false, 160); !errors.Is(err, ErrProposalConflict) {
228			t.Fatalf("alice change vote err=%v, want ErrProposalConflict", err)
229		}
230	
231		// ---- 执行之后：从未投票的最终代表不能借旧时间追加首次票据 ----
232	
233		// gina 传原投票窗口内的时间：提案已经计票，必须拒绝，且不能返回新票。
234		late, err := store.CastVote(id, "gina", true, 150)
235		if !errors.Is(err, ErrVoteRejected) {
236			t.Fatalf("first vote after tally err=%v, want ErrVoteRejected", err)
237		}
238		if late != nil {
239			t.Fatalf("rejected first vote returned a success-looking ballot: %+v", late)
240		}
241		if msg := err.Error(); !containsAll(msg, "already been tallied", "voting is closed") {
242			t.Fatalf("late first-vote error %q must report tally-closed, not a window/conflict error", msg)
243		}
244		if errors.Is(err, ErrProposalConflict) {
245			t.Fatalf("late first vote must be ErrVoteRejected, not conflict: %v", err)
246		}
247		// 投反对、窗口边界时间同样被拒，旧时间不能追加票据。
248		if b, err := store.CastVote(id, "gina", false, 199); !errors.Is(err, ErrVoteRejected) || b != nil {
249			t.Fatalf("gina against at 199: ballot=%+v err=%v, want rejection with no ballot", b, err)
250		}
251	
252		// ---- 全部重试与失败之后：治理记录、资金与凭据保持首次执行后的原样 ----
253		frozen := BalanceExpectation{Treasury: 900, Balances: map[string]int64{"audits": 100}}
254		assertExecutedGovernanceFrozen(t, store, id, receipt, "after retries", frozen)
255	
256		// 成功执行重试仍是同一份凭据，不二次扣款（动作留痕也逐字一致）。
257		execAgain, err := store.Execute(id, 9999)
258		if err != nil || !reflect.DeepEqual(execAgain, receipt) {
259			t.Fatalf("execute retry receipt=%+v err=%v, want original receipt %+v", execAgain, err, receipt)
260		}
261		if bal, _ := store.TreasuryBalance(); bal != 900 {
262			t.Fatalf("treasury changed on execute retry: %d", bal)
263		}
264		assertExecutedGovernanceFrozen(t, store, id, receipt, "after execute retry", frozen)
265	
266		// ---- 直接登记的已通过提案没有投票留痕，不能代替本使用条件 ----
267		mustRegister(t, store, "gip-direct", 0, "transfer:legal:5")
268		if _, err := store.Execute("gip-direct", 0); err != nil {
269			t.Fatalf("execute directly registered proposal: %v", err)
270		}
271		// register 来源在投票入口不可见：既没有票据可重试，也不接受新票。
272		if v, ok, err := store.VoteProposal("gip-direct"); err != nil || ok || v != nil {
273			t.Fatalf("registered proposal must not appear as a voting proposal: %+v ok=%v err=%v", v, ok, err)
274		}
275		if b, err := store.CastVote("gip-direct", "alice", true, 0); !errors.Is(err, ErrProposalNotFound) || b != nil {
276			t.Fatalf("vote on registered-only proposal: ballot=%+v err=%v, want ErrProposalNotFound", b, err)
277		}
278		// 登记提案自身按登记来源可查且已执行。
279		if rp, ok, err := store.Proposal("gip-direct"); err != nil || !ok || rp.State != "executed" {
280			t.Fatalf("registered proposal query=%+v ok=%v err=%v", rp, ok, err)
281		}
282	
283		// 直登提案的活动之后，受保护提案的票据重试与冻结状态仍然不变：
284		// 治理记录与原凭据逐字保留（直登提案的合法转账不改变它们）。
285		postDirect, err := store.CastVote(id, "dave", false, 1)
286		if err != nil || !reflect.DeepEqual(postDirect, againstFirst) {
287			t.Fatalf("dave retry after unrelated activity=%+v err=%v, want first ballot", postDirect, err)
288		}
289		assertExecutedGovernanceFrozen(t, store, id, receipt, "after unrelated direct proposal",
290			BalanceExpectation{Treasury: 895, Balances: map[string]int64{"audits": 100, "legal": 5}})
291	
292		// 凭据表新增的只是直登提案那一份；原提案凭据仍是 order=0 的同一份。
293		all, err := store.Receipts()
294		if err != nil || len(all) != 2 {
295			t.Fatalf("receipts=%v err=%v, want 2", all, err)
296		}
297		if !reflect.DeepEqual(all[0], receipt) || all[0].Order != 0 || all[0].ExecutedAt != 300 {
298			t.Fatalf("original receipt changed:\nwant=%+v\ngot =%+v", receipt, all[0])
299		}
300		if all[1].ProposalID != "gip-direct" || all[1].Order != 1 || all[1].ExecutedAt != 0 {
301			t.Fatalf("direct receipt=%+v, want gip-direct order=1 executed_at=0", all[1])
302		}
303	
304		// ---- 重开状态文件：重试结论、失败分类与全部冻结记录逐项一致 ----
305		if err := store.Close(); err != nil {
306			t.Fatalf("close: %v", err)
307		}
308		reopened, err := Open(path)
309		if err != nil {
310			t.Fatalf("reopen: %v", err)
311		}
312		defer reopened.Close()
313		postReopen := BalanceExpectation{Treasury: 895, Balances: map[string]int64{"audits": 100, "legal": 5}}
314		assertExecutedGovernanceFrozen(t, reopened, id, receipt, "after reopen", postReopen)
315		// 重开后同选择重试仍取回首次票据（含完整归集权重与首次时间）。
316		reAgainst, err := reopened.CastVote(id, "dave", false, 0)
317		if err != nil || !reflect.DeepEqual(reAgainst, againstFirst) {
318			t.Fatalf("dave retry after reopen=%+v err=%v, want first ballot", reAgainst, err)
319		}
320		reFor, err := reopened.CastVote(id, "alice", true, 100000)
321		if err != nil || !reflect.DeepEqual(reFor, forFirst) {
322			t.Fatalf("alice retry after reopen=%+v err=%v, want first ballot", reFor, err)
323		}
324		// 重开后改投仍是冲突，迟到代表的首次票仍被拒绝，且都不返回票据。
325		if b, err := reopened.CastVote(id, "dave", true, 150); !errors.Is(err, ErrProposalConflict) || b != nil {
326			t.Fatalf("change vote after reopen: ballot=%+v err=%v", b, err)
327		}
328		if b, err := reopened.CastVote(id, "gina", true, 150); !errors.Is(err, ErrVoteRejected) || b != nil {
329			t.Fatalf("gina first vote after reopen: ballot=%+v err=%v", b, err)
330		}
331		assertExecutedGovernanceFrozen(t, reopened, id, receipt, "after reopen retries", postReopen)
332	}
333	
334	// containsAll 判断 msg 是否同时包含全部子串。
335	func containsAll(msg string, subs ...string) bool {
336		for _, sub := range subs {
337			if !strings.Contains(msg, sub) {
338				return false
339			}
340		}
341		return true
342	}
343	
344	// BalanceExpectation 是断言时刻资金库与全部收款账户应有的余额。
345	type BalanceExpectation struct {
346		Treasury int64
347		Balances map[string]int64
348	}
349	
350	// assertExecutedGovernanceFrozen 断言已执行提案在投票重试/失败之后治理与资金
351	// 记录完全停留在首次执行后的状态：
352	//   - 状态 executed、来源 vote；两张票据的顺序/代表/归集权重/选择/首次时间不变；
353	//   - 首次计票的赞成 600、反对 150、参与 750、法定人数 600 与计票时间 200 不变；
354	//   - 资金库与全部收款账户余额与 want 完全一致（没有借重试产生的陌生账户）；
355	//   - 原提案的成功凭据仍是传入的同一份（order=0、executed_at=300、一项动作）。
356	func assertExecutedGovernanceFrozen(t *testing.T, s *Store, id string, receipt *Receipt, phase string, want BalanceExpectation) {
357		t.Helper()
358		v, ok, err := s.VoteProposal(id)
359		if err != nil || !ok {
360			t.Fatalf("%s: VoteProposal(%s) ok=%v err=%v", phase, id, ok, err)
361		}
362		if v.Source != "vote" || v.State != "executed" {
363			t.Fatalf("%s: source=%s state=%s, want vote/executed", phase, v.Source, v.State)
364		}
365		if v.Quorum != 600 || v.TotalWeight != 850 {
366			t.Fatalf("%s: quorum=%d total=%d, want 600/850", phase, v.Quorum, v.TotalWeight)
367		}
368		// 票据数量、顺序、选择、权重与首次时间保持原样。
369		if len(v.Ballots) != 2 {
370			t.Fatalf("%s: ballots=%+v, want exactly 2", phase, v.Ballots)
371		}
372		b0, b1 := v.Ballots[0], v.Ballots[1]
373		if b0.Representative != "dave" || b0.Weight != 150 || b0.Support || b0.VotedAt != 150 {
374			t.Fatalf("%s: ballot 0=%+v, want dave/150/against/150", phase, b0)
375		}
376		if b1.Representative != "alice" || b1.Weight != 600 || !b1.Support || b1.VotedAt != 160 {
377			t.Fatalf("%s: ballot 1=%+v, want alice/600/for/160", phase, b1)
378		}
379		// 首次计票结论不因重试或执行而改变。
380		if v.Tally == nil {
381			t.Fatalf("%s: tally missing", phase)
382		}
383		if v.Tally.ForWeight != 600 || v.Tally.AgainstWeight != 150 || v.Tally.Turnout != 750 ||
384			v.Tally.Quorum != 600 || !v.Tally.Passed || v.Tally.TalliedAt != 200 {
385			t.Fatalf("%s: tally=%+v, want for=600 against=150 turnout=750 quorum=600 passed at=200",
386				phase, v.Tally)
387		}
388		// 再次计票返回首次结论，时间不被替换。
389		again, err := s.TallyVote(id, 9999)
390		if err != nil || again.TalliedAt != 200 || again.ForWeight != 600 ||
391			again.AgainstWeight != 150 || again.Turnout != 750 {
392			t.Fatalf("%s: repeat tally=%+v err=%v, want first verdict at 200", phase, again, err)
393		}
394		// 资金停留在断言时刻应有的数值，账户集合逐字一致。
395		if bal, _ := s.TreasuryBalance(); bal != want.Treasury {
396			t.Fatalf("%s: treasury=%d, want %d", phase, bal, want.Treasury)
397		}
398		snap, err := s.BalanceSnapshot()
399		if err != nil {
400			t.Fatalf("%s: snapshot: %v", phase, err)
401		}
402		if len(snap.Balances) != len(want.Balances) {
403			t.Fatalf("%s: balance accounts=%+v, want %+v", phase, snap.Balances, want.Balances)
404		}
405		for account, balance := range want.Balances {
406			if got := snap.Balances[account]; got != balance {
407				t.Fatalf("%s: balance of %s=%d, want %d", phase, account, got, balance)
408			}
409		}
410		// 原提案凭据仍是同一份；执行时间与动作留痕不变。
411		got, ok, err := s.Receipt(id)
412		if err != nil || !ok {
413			t.Fatalf("%s: receipt ok=%v err=%v", phase, ok, err)
414		}
415		if !reflect.DeepEqual(got, receipt) {
416			t.Fatalf("%s: receipt changed:\nwant=%+v\ngot =%+v", phase, receipt, got)
417		}
418	}
