		cleanup()
		return false, err
	}
	if err := tmp.Sync(); err != nil {
		_ = tmp.Close()
		cleanup()
		return false, err
	}
	if err := tmp.Close(); err != nil {
		cleanup()
		return false, err
	}
	if err := os.Chmod(tmpName, 0o600); err != nil {
		cleanup()
		return false, err
	}
	if err := os.Rename(tmpName, s.path); err != nil {
		cleanup()
		return false, err
	}
